CREATE OR REPLACE FUNCTION jobseek_job_posting_default_source_identity()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.source_identity IS NULL THEN
        NEW.source_identity := NEW.source_url;
    ELSIF TG_OP = 'UPDATE'
          AND NEW.source_identity IS NOT DISTINCT FROM OLD.source_identity
          AND OLD.source_identity IS NOT DISTINCT FROM OLD.source_url
    THEN
        -- Preserve URL-as-identity semantics for old runtimes and bounded
        -- canonicalization migrations. Explicit provider identities differ
        -- from OLD.source_url and are therefore never rewritten here.
        NEW.source_identity := NEW.source_url;
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER job_posting_default_source_identity
BEFORE INSERT OR UPDATE OF source_url ON job_posting
FOR EACH ROW
EXECUTE FUNCTION jobseek_job_posting_default_source_identity();;

DO $$
DECLARE
    intern_seniority_id integer;
BEGIN
    -- Taxonomy tables are populated by sync rather than Alembic on a brand-new
    -- database, so an empty installation has nothing to migrate yet.
    IF to_regclass('public.seniority') IS NULL THEN
        RETURN;
    END IF;

    SELECT id
    INTO intern_seniority_id
    FROM public.seniority
    WHERE slug = 'intern';

    IF intern_seniority_id IS NULL THEN
        RETURN;
    END IF;

    UPDATE public.job_posting
    SET seniority_id = intern_seniority_id,
        employment_type = NULL,
        updated_at = now()
    WHERE employment_type = 'internship';
END
$$;

DO $migration$
DECLARE
    canonical_id uuid;
    duplicate_id uuid;
BEGIN
    SELECT id INTO canonical_id FROM company WHERE slug = 'starbucks';
    SELECT id INTO duplicate_id FROM company WHERE slug = 'starbucks-china';

    IF duplicate_id IS NULL THEN
        RETURN;
    END IF;
    IF canonical_id IS NULL THEN
        RAISE EXCEPTION
            'cannot merge starbucks-china: canonical starbucks company is missing';
    END IF;

    UPDATE job_board
    SET company_id = canonical_id,
        updated_at = now()
    WHERE company_id = duplicate_id;

    UPDATE job_posting
    SET company_id = canonical_id,
        updated_at = now()
    WHERE company_id = duplicate_id;

    IF to_regclass('public.murmur_accept_log') IS NOT NULL THEN
        EXECUTE
            'UPDATE murmur_accept_log SET company_id = $1 WHERE company_id = $2'
            USING canonical_id, duplicate_id;
    END IF;

    IF to_regclass('public.company_description') IS NOT NULL THEN
        EXECUTE
            'DELETE FROM company_description WHERE company_id = $1'
            USING duplicate_id;
    END IF;

    IF EXISTS (SELECT 1 FROM job_board WHERE company_id = duplicate_id)
       OR EXISTS (SELECT 1 FROM job_posting WHERE company_id = duplicate_id) THEN
        RAISE EXCEPTION
            'cannot delete starbucks-china: crawler references remain';
    END IF;

    DELETE FROM company WHERE id = duplicate_id;
    IF FOUND IS NOT TRUE THEN
        RAISE EXCEPTION 'starbucks-china disappeared during identity merge';
    END IF;
END
$migration$;;

CREATE OR REPLACE FUNCTION public.jobseek_lightpanda_b0_enforce_current_routing_epoch()
RETURNS trigger
LANGUAGE plpgsql
VOLATILE
PARALLEL UNSAFE
SECURITY INVOKER
SET search_path = pg_catalog
AS $$
DECLARE
    current_epoch bigint;
    allocator_called boolean;
BEGIN
    IF NEW.engine_owner IS DISTINCT FROM 'go' THEN
        RETURN NEW;
    END IF;
    SELECT last_value, is_called
    INTO current_epoch, allocator_called
    FROM public.lightpanda_b0_routing_epoch_seq;
    IF allocator_called IS DISTINCT FROM true
        OR current_epoch IS DISTINCT FROM NEW.routing_epoch
    THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P0001',
            MESSAGE = 'lightpanda_b0_write_fence_rejected',
            DETAIL = 'routing_epoch_not_current';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER lightpanda_b0_write_fence_current_epoch
BEFORE INSERT OR UPDATE ON public.lightpanda_b0_write_fence
FOR EACH ROW
EXECUTE FUNCTION public.jobseek_lightpanda_b0_enforce_current_routing_epoch();

CREATE OR REPLACE FUNCTION public.jobseek_lightpanda_b0_enforce_current_routing_epoch()
RETURNS trigger
LANGUAGE plpgsql
VOLATILE
PARALLEL UNSAFE
SECURITY INVOKER
SET search_path = pg_catalog
AS $$
DECLARE
    current_epoch bigint;
    allocator_called boolean;
BEGIN
    IF NEW.engine_owner IS DISTINCT FROM 'go' THEN
        RETURN NEW;
    END IF;
    -- Held until the surrounding fence transaction ends. An exclusive
    -- allocator therefore orders either wholly before or wholly after this
    -- write; it cannot advance between the check and commit.
    PERFORM pg_catalog.pg_advisory_xact_lock_shared(7544422533504811009);
    SELECT last_value, is_called
    INTO current_epoch, allocator_called
    FROM public.lightpanda_b0_routing_epoch_seq;
    IF allocator_called IS DISTINCT FROM true
        OR current_epoch IS DISTINCT FROM NEW.routing_epoch
    THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P0001',
            MESSAGE = 'lightpanda_b0_write_fence_rejected',
            DETAIL = 'routing_epoch_not_current';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION inherit_board_tdm_reservation() RETURNS trigger
        LANGUAGE plpgsql AS $$
        DECLARE reserved boolean;
        BEGIN
            -- Serialize inserts/reassignments with a board reservation so a
            -- concurrent new posting cannot escape the board-wide update.
            SELECT tdm_reserved INTO reserved FROM job_board
            WHERE id = NEW.board_id FOR SHARE;
            NEW.tdm_reserved := NEW.tdm_reserved OR COALESCE(reserved, false);
            RETURN NEW;
        END $$;
        CREATE TRIGGER posting_inherit_tdm_reservation
        BEFORE INSERT OR UPDATE OF board_id, tdm_reserved ON job_posting
        FOR EACH ROW EXECUTE FUNCTION inherit_board_tdm_reservation();

        CREATE FUNCTION propagate_board_tdm_reservation() RETURNS trigger
        LANGUAGE plpgsql AS $$
        BEGIN
            IF NEW.tdm_reserved AND NOT OLD.tdm_reserved THEN
                UPDATE job_posting SET tdm_reserved = true,
                    updated_at = clock_timestamp()
                WHERE board_id = NEW.id AND NOT tdm_reserved;
            END IF;
            RETURN NEW;
        END $$;
        CREATE TRIGGER board_propagate_tdm_reservation
        AFTER UPDATE OF tdm_reserved ON job_board
        FOR EACH ROW EXECUTE FUNCTION propagate_board_tdm_reservation();;

-- Durable ordinary ownership; projection loss never changes the DB owner.
CREATE TABLE public.ordinary_worker_ownership_plan (
    plan_sha256 text PRIMARY KEY CHECK (plan_sha256 ~ '^[0-9a-f]{64}$'),
    routing_epoch bigint NOT NULL CHECK (routing_epoch BETWEEN 1 AND 9999999999999),
    source_revision text NOT NULL CHECK (source_revision ~ '^[0-9a-f]{40}$'),
    payload text NOT NULL CHECK (octet_length(payload) BETWEEN 1 AND 16777216),
    state text NOT NULL DEFAULT 'staged' CHECK (state IN ('staged','active','retired')),
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    CHECK (plan_sha256 = encode(sha256(convert_to(payload,'UTF8')),'hex')),
    CHECK (jsonb_typeof(payload::jsonb) = 'object'),
    CHECK ((payload::jsonb ->> 'version' = 'jobseek.ordinary.ownership/v1') IS TRUE),
    CHECK ((payload::jsonb ->> 'routing_epoch' = routing_epoch::text) IS TRUE),
    CHECK ((payload::jsonb ->> 'source_revision' = source_revision) IS TRUE),
    CHECK ((jsonb_typeof(payload::jsonb -> 'members') = 'array') IS TRUE),
    CHECK ((jsonb_array_length(payload::jsonb -> 'members') BETWEEN 1 AND 20000) IS TRUE)
);
CREATE UNIQUE INDEX ordinary_worker_one_active_plan
ON public.ordinary_worker_ownership_plan ((true)) WHERE state='active';

CREATE FUNCTION public.jobseek_ordinary_ownership_transition()
RETURNS trigger LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY INVOKER
SET search_path=pg_catalog AS $$
DECLARE
    current_epoch bigint;
    allocator_called boolean;
BEGIN
    -- Same lock order as ordinary claims/writes/reaping and epoch retirement.
    PERFORM pg_catalog.pg_advisory_xact_lock(7544422533504811010);
    PERFORM pg_catalog.pg_advisory_xact_lock_shared(7544422533504811009);
    IF TG_OP='DELETE' THEN
        IF OLD.state <> 'staged' THEN
            RAISE EXCEPTION 'ordinary_ownership_retained';
        END IF;
        RETURN OLD;
    END IF;
    IF TG_OP='INSERT' AND NEW.state <> 'staged' THEN
        RAISE EXCEPTION 'ordinary_ownership_stage_required';
    END IF;
    IF TG_OP='UPDATE' THEN
        IF NEW.plan_sha256 IS DISTINCT FROM OLD.plan_sha256
            OR NEW.routing_epoch IS DISTINCT FROM OLD.routing_epoch
            OR NEW.source_revision IS DISTINCT FROM OLD.source_revision
            OR NEW.payload IS DISTINCT FROM OLD.payload
            OR NEW.created_at IS DISTINCT FROM OLD.created_at
            OR NOT ((OLD.state='staged' AND NEW.state='active')
                OR (OLD.state='active' AND NEW.state='retired'))
        THEN
            RAISE EXCEPTION 'ordinary_ownership_transition_rejected';
        END IF;
    END IF;
    IF TG_OP='INSERT' OR NEW.state='active' THEN
        SELECT last_value,is_called INTO current_epoch,allocator_called
        FROM public.lightpanda_b0_routing_epoch_seq;
        IF allocator_called IS DISTINCT FROM true
            OR current_epoch IS DISTINCT FROM NEW.routing_epoch
        THEN
            RAISE EXCEPTION 'ordinary_ownership_epoch_rejected';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER ordinary_worker_ownership_transition
BEFORE INSERT OR UPDATE OR DELETE ON public.ordinary_worker_ownership_plan
FOR EACH ROW EXECUTE FUNCTION public.jobseek_ordinary_ownership_transition();;

CREATE TABLE public.source_coverage_scope (
    board_id uuid PRIMARY KEY REFERENCES public.job_board(id) ON DELETE CASCADE,
    revision uuid NOT NULL DEFAULT gen_random_uuid(),
    tracked_since timestamptz NOT NULL DEFAULT clock_timestamp(),
    effective_config_sha256 char(64)
        CHECK (effective_config_sha256 IS NULL OR effective_config_sha256 ~ '^[0-9a-f]{64}$')
);
INSERT INTO public.source_coverage_scope(board_id)
SELECT id FROM public.job_board;

CREATE TABLE public.source_coverage_check (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    board_id uuid NOT NULL REFERENCES public.job_board(id) ON DELETE CASCADE,
    revision uuid NOT NULL,
